INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO', 'PRE_.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH', 'pre_technical', 7, 'Name the strands of Pre-Technical Studies and say how it is used in daily life', ARRAY['PRE_.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.a', 'PRE_.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.b']::text[], 'The child names the five strands (foundations and safety, communication and drawing, materials, tools and production, entrepreneurship), puts an activity in the right strand, and says the learning area is used in homes, workshops, farms, shops and offices by everybody. The child does not say it is only for boys, only for people who will become mechanics, or only done in a school workshop. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which strand a described activity belongs to","say how Pre-Technical Studies helps in a described daily-life job","say who uses Pre-Technical knowledge: girls, boys, workers, businesses","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS', 'PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_', 'pre_technical', 7, 'Identify safety threats: falls, slips, trips, road crashes, fires and threats to devices', ARRAY['PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.a']::text[], 'The child names a fall (from a height), a slip (on a wet or smooth floor), a trip (over an object in the way), a road crash and a fire from sparks, flames, faulty wires or cooking, and names theft, floods or fire, and hardware failure as threats to a device. The child does not call all of them "accidents that cannot be prevented". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the threat in a described situation","say what could go wrong with a device","pick the situation that is a slip or a trip","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_', 'pre_technical', 7, 'Identify online threats and say what to do about them', ARRAY['PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.a']::text[], 'The child names cyberbullying (hurting someone online), impersonation (pretending to be someone else), phishing (a fake message that tricks you into giving a password or PIN), hacking (breaking into an account or device) and an unknown friend request, and says: do not share a PIN or password, do not open unknown links, do not accept strangers, and tell a trusted adult. The child does not say a message is safe because it looks official. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the online threat in a described message","say what to do with a request from a stranger","pick the safe action","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_', 'pre_technical', 7, 'Give the safety rules for working with materials and tools', ARRAY['PRE_.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.b']::text[], 'The child says: wear the right protective clothing (overall, closed shoes, gloves, goggles), tie back long hair and do not wear loose clothes near machines, keep the floor and the bench clean and dry, use a tool only for its job, never run or play in the workshop, switch off and unplug a machine before changing anything, report every injury or accident to the teacher, and know where the fire sand, extinguisher and first aid box are. Power, heat and sharp tools are used with a teacher. The child does not say a small cut need not be reported. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the rule that prevents a described accident","say what a worker should do in a described situation","decide who broke a rule in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'PRE_.G7.FOUNDA.COMPUTER_CONCEPTS', 'pre_technical', 7, 'Explain data and information and the characteristics of a computer', ARRAY['PRE_.G7.FOUNDA.COMPUTER_CONCEPTS.a']::text[], 'The child says data is raw facts and figures, information is data that has been processed so that it means something, and names speed, accuracy, versatility, reliability, diligence (it does not get tired), storage and consistency, with an example of each. The child says a computer follows instructions and gives wrong output from wrong input. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether an item is data or information","pick the characteristic described","say what a computer will do with wrong input","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY', 'PRE_.G7.FOUNDA.COMPUTER_CONCEPTS', 'pre_technical', 7, 'Classify computers by function, purpose and size', ARRAY['PRE_.G7.FOUNDA.COMPUTER_CONCEPTS.b']::text[], 'The child says analogue computers work with continuous measurements, digital computers work with digits (0 and 1) and hybrid computers have both; general-purpose computers do many jobs and special-purpose computers one; and super, mainframe, mini and micro computers differ in size and power, with desktops, laptops, tablets and smartphones as micro computers. The child does not say a smartphone is not a computer. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say how a computer is classified by function, purpose or size","sort named computers into groups","pick the type that fits a described job","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE', 'PRE_.G7.FOUNDA.COMPUTER_CONCEPTS', 'pre_technical', 7, 'Give the correct steps for using a computer: start up, open a program, save a file with a clear name, and shut down properly', ARRAY['PRE_.G7.FOUNDA.COMPUTER_CONCEPTS.c']::text[], 'Orders the steps of a computer task (switch on, log in, open the program by double-clicking its icon or from the Start menu, work, save with a clear file name in a chosen folder, close the program, shut down from the operating system before switching off at the socket), and says what happens when work is not saved or the power is cut without shutting down (lost work, damaged files). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["put the steps of a task in order","say what goes wrong when a step is skipped","pick the right mouse or keyboard action"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE', 'PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING', 'pre_technical', 7, 'Say why drawing is used to communicate, and tell artistic drawing from technical drawing', ARRAY['PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING.a', 'PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING.b']::text[], 'The child says a drawing shows shape, size and parts that words describe badly and that anyone can read the same plan, and that an artistic drawing shows feeling or beauty while a technical drawing gives exact shape and size by rules so a worker can make the thing. The child does not say technical drawings are for decoration or that artists never measure. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a drawing communicates better than words","sort a described drawing as artistic or technical","say who uses technical drawings","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES', 'PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING', 'pre_technical', 7, 'Name the types of lines in drawing and what each is used for', ARRAY['PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING.d']::text[], 'The child says the thick continuous line draws the outline and visible edges, the thin continuous line draws dimension lines and projection lines, the dashed line shows hidden detail, and the chain line (long and short dashes) shows the centre of a round part or the line of symmetry. Drawing the lines is practical work seen by the teacher. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a given line type shows","pick the line type for a given job","read a described line on a plan","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS', 'PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING', 'pre_technical', 7, 'Read the common symbols and abbreviations used in drawing', ARRAY['PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING.e']::text[], 'The child says ⌀ means diameter, R radius, ⊥ perpendicular (at a right angle), ▢ square, ℄ centre line, and DRG drawing, A/F across flats, A/C across corners, I/D inside diameter and O/D outside diameter. The child does not mix up diameter and radius or inside and outside diameter. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a symbol or abbreviation means","pick the symbol for a described meaning","read a note on a drawing","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING', 'PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING', 'pre_technical', 7, 'State the rules for printing letters and numbers on a technical drawing: capitals, single strokes, guide lines, even height and spacing', ARRAY['PRE_.G7.COMMUN.INTRODUCTION_TO_DRAWING.c']::text[], 'Says that notes on a technical drawing are printed in plain capital (upper case) letters and numbers, made with single strokes, all upright (or all at the same slope), the same height between two faint guide lines, with even gaps between letters and a wider gap between words, and picks the note that follows these rules. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["pick the correctly printed note","say which rule a printed note breaks","say what guide lines are for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES', 'PRE_.G7.COMMUN.FREE_HAND_SKETCHING', 'pre_technical', 7, 'Explain the principles of free-hand sketching', ARRAY['PRE_.G7.COMMUN.FREE_HAND_SKETCHING.a']::text[], 'The child says a free-hand sketch is drawn quickly without a ruler or compass, starts with light lines that are firmed up later, looks first at the whole shape and its proportions, and uses the arm and a loose hand, not tight fingers. The child does not say a sketch must be exact and ruled, or that dark pressed lines come first. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right way to start a sketch","say what free-hand sketching is","decide who followed the principles","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'PRE_.G7.COMMUN.FREE_HAND_SKETCHING', 'pre_technical', 7, 'Name the techniques of free-hand sketching and shading', ARRAY['PRE_.G7.COMMUN.FREE_HAND_SKETCHING.b', 'PRE_.G7.COMMUN.FREE_HAND_SKETCHING.c', 'PRE_.G7.COMMUN.FREE_HAND_SKETCHING.d']::text[], 'The child says the box method fits a light box round the object first, the centreline method draws a centre line and builds a matching shape on each side, the hand compass method draws a circle or an arc by turning the paper or the hand about a fixed finger, and that shading uses hatching (parallel lines), cross-hatching (two sets of lines crossing), stippling (dots) and blending (smooth change from dark to light). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which technique a described step belongs to","pick the technique for a given job","match a shading style to its marks","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'PRE_.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI', 'pre_technical', 7, 'Say why ICT tools matter in communication and what each tool is used for', ARRAY['PRE_.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.a', 'PRE_.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.b', 'PRE_.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.c']::text[], 'The child says ICT tools carry messages fast, over long distances and to many people, and keep a record; email sends written messages and files, a mobile phone calls and sends texts, video conferencing lets people see and hear one another live over the internet, social networking shares messages and pictures with groups, and online collaboration lets several people work on one file. The child says some tools need airtime or data and an internet link, and does not say ICT tools cost nothing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say why ICT tools help communication","pick the tool for a described message","say what a tool needs (airtime, data, an internet link)","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL', 'PRE_.G7.MATERI.INTRODUCTION_TO_MATERIAL', 'pre_technical', 7, 'Say what a material is and sort materials as metallic or non-metallic', ARRAY['PRE_.G7.MATERI.INTRODUCTION_TO_MATERIAL.a', 'PRE_.G7.MATERI.INTRODUCTION_TO_MATERIAL.b']::text[], 'The child says a material is what a thing is made from, and sorts steel, aluminium, copper and iron as metallic, and wood, stone, plastic, rubber, glass, ceramics, paper and cement as non-metallic, and says a finished product (a chair, a sufuria) is not a material. The child does not call glass or a stone metallic because it is hard or shiny. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether a named material is metallic or non-metallic","pick the material a given product is made from","sort a list of local materials","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE', 'PRE_.G7.MATERI.INTRODUCTION_TO_MATERIAL', 'pre_technical', 7, 'Describe sustainable ways of using materials in production', ARRAY['PRE_.G7.MATERI.INTRODUCTION_TO_MATERIAL.c']::text[], 'The child says sustainable use means using materials so they last and are not wasted: plan the cut to waste less, use offcuts, repair and reuse, recycle scrap metal and plastic, choose local materials, and plant trees where timber is taken. The child does not say plentiful materials may be wasted. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the sustainable choice in a described job","say what reduce, reuse and recycle mean","decide which worker saves materials","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES', 'PRE_.G7.MATERI.METALLIC_MATERIALS', 'pre_technical', 7, 'Identify steel, aluminium and copper by appearance and a magnet', ARRAY['PRE_.G7.MATERI.METALLIC_MATERIALS.a']::text[], 'The child says steel is grey, hard and sticks to a magnet, aluminium is light, silvery and does not stick to a magnet, and copper is reddish-brown and does not stick to a magnet. The child does not say aluminium is a kind of steel or that all metals stick to a magnet. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which metal a described piece is","say what a magnet test shows","pick the metal that matches a checklist","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES', 'PRE_.G7.MATERI.METALLIC_MATERIALS', 'pre_technical', 7, 'Describe the physical properties of metals: magnetism, conducting heat and electricity, appearance', ARRAY['PRE_.G7.MATERI.METALLIC_MATERIALS.b']::text[], 'The child says metals are usually shiny, conduct heat and electricity (copper very well), can be hammered into sheets and drawn into wire, and that only iron and steel (not aluminium or copper) stick to a magnet and rust. The child does not say every metal is magnetic or that every metal rusts. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which property a described test shows","say whether a metal conducts, sticks to a magnet or rusts","pick the metal with a given property","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES', 'PRE_.G7.MATERI.METALLIC_MATERIALS', 'pre_technical', 7, 'Relate metals to their uses', ARRAY['PRE_.G7.MATERI.METALLIC_MATERIALS.c']::text[], 'The child says copper is used for electric wire because it conducts well, aluminium for sufurias and window frames because it is light and conducts heat, and steel for nails, panga blades, jembe blades and bridges because it is hard and strong. The child gives the property that makes the metal suit the job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the metal for a given use","say which property makes a metal fit a use","match a jua kali product to its metal","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS', 'PRE_.G7.MATERI.NON_METALLIC_MATERIALS', 'pre_technical', 7, 'Identify non-metallic materials and sort them as natural or synthetic', ARRAY['PRE_.G7.MATERI.NON_METALLIC_MATERIALS.a', 'PRE_.G7.MATERI.NON_METALLIC_MATERIALS.b']::text[], 'The child says natural materials come from plants, animals or the ground (wood, stone, cotton, wool, sisal, leather) and synthetic materials are made by people from chemicals (plastics such as polythene and PVC, nylon, synthetic rubber). The child does not say synthetic means "fake" or that natural means "never changed by people". Materials that are made from natural ones (paper, glass, cement, ceramics) are left to the teacher to place. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether a named material is natural or synthetic","say what synthetic means","sort a list of materials"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES', 'PRE_.G7.MATERI.NON_METALLIC_MATERIALS', 'pre_technical', 7, 'Describe the physical properties of non-metallic materials: colour, texture, hardness, fire resistance', ARRAY['PRE_.G7.MATERI.NON_METALLIC_MATERIALS.c']::text[], 'The child says wood and paper burn, plastics soften and melt in heat, stone and ceramics (clay pots, bricks, tiles) do not burn, glass is hard but breaks, rubber stretches and returns, and plastics and rubber do not carry electricity. The child does not say all non-metals burn or that hard means it cannot break. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which property a described test shows","pick the material that has a given property","say what happens to a material in heat","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES', 'PRE_.G7.MATERI.NON_METALLIC_MATERIALS', 'pre_technical', 7, 'Relate non-metallic materials to their uses', ARRAY['PRE_.G7.MATERI.NON_METALLIC_MATERIALS.d']::text[], 'The child says wood suits furniture and handles, stone building foundations, plastic water tanks, pipes and jerricans, rubber tyres and gloves, glass windows, ceramics tiles and sinks, and cement joins blocks and makes concrete, and gives the property that makes each suit its job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the material for a given use","say which property makes a material fit a use","match a local product to its material","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS', 'PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU', 'pre_technical', 7, 'Identify measuring tools and what each measures', ARRAY['PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU.a']::text[], 'The child says a tape measure measures long lengths and curved things, a steel rule short lengths (in cm and mm), callipers the thickness or diameter of a round or small part (inside or outside), a weighing balance mass, a stopwatch time, an ammeter current in amperes and a voltmeter voltage in volts. The child does not say a voltmeter measures current. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a named measuring tool measures","pick the tool for a quantity","say what a reading is in","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS', 'PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU', 'pre_technical', 7, 'Identify marking out tools and what each does', ARRAY['PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU.a']::text[], 'The child says a divider marks circles and arcs and steps off equal distances, a try-square checks and marks right angles, a marking gauge scribes a line parallel to an edge, a dot punch makes a small dent to mark a centre, a scriber scratches a fine line on metal, a pencil marks wood and paper, and a marking knife cuts a fine line on wood to start a saw cut. The child does not say a dot punch makes the hole or a divider cuts. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a named marking out tool does","pick the tool for a marking job","say which surface a tool marks","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU', 'pre_technical', 7, 'Choose the right measuring and marking out tool for a task', ARRAY['PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU.b']::text[], 'The child chooses a tape measure for the length of a wall or a person, callipers for the diameter of a bolt, a try-square for a right angle on timber, a divider for a circle on sheet metal, a dot punch before drilling, a scriber for a line on steel, and says why the other tool would give a poorer result. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the tool for a described task","say why one tool fits better than another","decide who chose well in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE', 'PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU', 'pre_technical', 7, 'Say how to care for measuring and marking out tools', ARRAY['PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU.d']::text[], 'The child says tools are wiped clean and dry after use, steel tools get a light film of oil against rust, they are kept in a dry box or rack, the points of dividers and scribers are covered, callipers and steel rules are not dropped, bent, or used as hammers or levers, and tools are returned after the lesson. The child does not say tools may be left wet or thrown in a heap. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the way to care for a tool","say what goes wrong when a tool is not cared for","decide who looked after tools well","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE', 'PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU', 'pre_technical', 7, 'Give the correct way to use measuring and marking out tools: read from the zero mark with the eye straight above, hold the try-square against a straight edge, scribe and punch in order', ARRAY['PRE_.G7.TOOLS_.MEASURING_AND_MARKING_OU.c']::text[], 'Says to measure from the zero mark (not the worn end of a ruler), read the scale with the eye straight above the mark, hold the stock of a try-square firmly against a straight face edge, scribe away from the body, and dot-punch only where two scribed lines cross; picks the use that gives a true mark. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. The practical part (the drawing, the item made, the tool or computer used) is marked by the teacher with the KICD rubric, never by a tap.', '["say which way of using a tool gives a true reading","put the marking-out steps in order","find the mistake in a described use"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY', 'PRE_.G7.TOOLS_.COMPUTER_HARDWARE', 'pre_technical', 7, 'Classify computer hardware as input, output (hardcopy or softcopy) or storage', ARRAY['PRE_.G7.TOOLS_.COMPUTER_HARDWARE.a', 'PRE_.G7.TOOLS_.COMPUTER_HARDWARE.b']::text[], 'The child says input devices send data in (keyboard, mouse, scanner, microphone, touch screen, digital camera), output devices give results out as hardcopy (printer, plotter: on paper) or softcopy (monitor, speaker, projector: on a screen or as sound), and storage devices keep data (hard disk, flash disk, memory card, CD or DVD). Hardware is the parts you can touch. The child does not call a printer an input device. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether a device is input, output or storage","pick the device for a described job","say hardcopy or softcopy","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE', 'pre_technical', 7, 'Explain what an entrepreneur is and why entrepreneurship matters in the community', ARRAY['PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.a']::text[], 'The child says an entrepreneur sees a need or chance, starts a business and takes the risk to run it; entrepreneurship is doing that; and it matters because it makes jobs, goods and services, income and taxes, and uses local skills and materials. The child does not say every worker is an entrepreneur, that only rich people can be, or that it matters only to the owner. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say whether a person is an entrepreneur","say how a business helps its community","pick the importance of entrepreneurship","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE', 'pre_technical', 7, 'Describe the qualities of an entrepreneur', ARRAY['PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.b']::text[], 'The child says an entrepreneur is creative, hardworking, honest, determined (does not give up at the first failure), a good communicator, self-confident and takes calculated risks (counts the cost first). The child does not say risk-taking means gambling or that cheating customers is clever. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say which quality a described person shows","pick the quality that fits a situation","say what a good entrepreneur does when a business fails","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS', 'PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE', 'pre_technical', 7, 'Name the sources of business ideas', ARRAY['PRE_.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.c']::text[], 'The child says business ideas come from the learner''s own skills and hobbies, from problems and needs in the community, from watching other businesses and improving them, from waste that can be reused, from media, the internet and trade fairs, and from family and friends. The child does not say an idea must be completely new or that a lot of money must come first. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say where a described business idea came from","pick a source of a business idea","say what makes an idea workable","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'PRE_.G7.ENTREP.UNIT', 'pre_technical', 7, 'Explain the factors to consider when locating a production unit', ARRAY['PRE_.G7.ENTREP.UNIT.a']::text[], 'The child says a production unit (a posho mill, salon, barber shop, welding workshop, cybercafe) is placed with these in mind: nearness to customers, to raw materials, to labour, roads and transport, power and water, safety from theft, the cost of rent or land, competition and permits. The child does not say the town centre is always best or that cheapest rent is the only factor. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the factor that decides the place for a described business","say what is wrong with a poor site","decide who chose a site well","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_SIZE', 'PRE_.G7.ENTREP.UNIT', 'pre_technical', 7, 'Analyse the factors that decide the size of a production unit', ARRAY['PRE_.G7.ENTREP.UNIT.b']::text[], 'The child says the size of a unit depends on the capital available, the size of the market (how much customers will buy), the supply of raw materials, labour and skills, the machines and technology, the space, how well it can be managed, and the law. The child does not say bigger is always better. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the factor that limits the size of a described business","say why starting small can be wise","decide who sized a business sensibly","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS', 'PRE_.G7.ENTREP.FINANCIAL_GOALS', 'pre_technical', 7, 'Explain why financial goals matter and the factors to consider when setting them', ARRAY['PRE_.G7.ENTREP.FINANCIAL_GOALS.a', 'PRE_.G7.ENTREP.FINANCIAL_GOALS.b']::text[], 'The child says financial goals give direction, help save for needs and emergencies, show progress and stop wasteful spending, and are set with the person''s income, expenses, needs before wants, the cost of the goal and the time available in mind. The child does not say goals are only for rich people or that a goal is the same as a wish. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say why a person sets a financial goal","pick the factor to think about before setting a goal","say what a sensible goal considers","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART', 'PRE_.G7.ENTREP.FINANCIAL_GOALS', 'pre_technical', 7, 'Tell a SMART financial goal from a weak one', ARRAY['PRE_.G7.ENTREP.FINANCIAL_GOALS.c']::text[], 'The child says SMART goals are Specific, Measurable, Achievable, Realistic and Time-bound, picks the goal that names an amount, a way and a date, and says which part a weak goal such as "save more money" leaves out. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what S, M, A, R and T stand for","pick the SMART goal","say which letter a weak goal fails","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'PRE_.G7.ENTREP.FINANCIAL_GOALS', 'pre_technical', 7, 'Work out simple savings, cost and profit for a financial goal', ARRAY['PRE_.G7.ENTREP.FINANCIAL_GOALS.c']::text[], 'The child works out weeks to save as the goal divided by the amount saved a week, profit per item as selling price minus buying price, total profit as profit per item times the number sold, and compares the answer with the goal. The child does not call the selling price the profit. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["work out how many weeks a saving goal takes","work out profit on a batch of goods","say whether a goal is reached","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
