INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'MATH.G6.MEASUR.MONEY.BUYING_SELLING_PRICE', 'skill', 'essential', 'Mathematics taught the measuring, drawing or money idea first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'MATH.G6.MEASUR.MONEY.PROFIT_FROM_SALES', 'skill', 'essential', 'Profit from sales. Proposed, to confirm by a Pre-Technical Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO.M_PI_TOOLS_ONLY', 'PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO', 'Thinks Pre-Technical Studies is only about handling tools and making things.', '{"question":"Which of these is part of Pre-Technical Studies?","wrong_answer":"Only using tools in the workshop","correct_answer":"Tools, drawing, materials, computers, safety and starting a business"}'::jsonb, 'The workshop lessons are the most memorable, so the learner forgets drawing, computers, materials and business.', 'Offer "Only using tools in the workshop" next to the right answer and ask the question again in a new context.', 'Show the five strands on a chart and sort ten activities (budgeting, sketching, using a computer, choosing timber, safety rules) into them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO.M_PI_BOYS', 'PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO', 'Thinks Pre-Technical Studies is for boys or for learners who will not go on to other careers.', '{"question":"Who uses Pre-Technical knowledge?","wrong_answer":"Only boys who will become mechanics","correct_answer":"Girls and boys, in many jobs and in daily life"}'::jsonb, 'Workshop jobs around the learner are mostly done by men, so the subject looks like a boys'' subject.', 'Offer "Only boys who will become mechanics" next to the right answer and ask the question again in a new context.', 'Show women engineers, tailors, architects and business owners from Kenya; ask which strand each one uses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO.M_PI_SCHOOL_ONLY', 'PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO', 'Thinks Pre-Technical knowledge is used only in a school workshop.', '{"question":"Where is Pre-Technical knowledge used in daily life?","wrong_answer":"Only in the school workshop","correct_answer":"At home, in shops, on farms and in workshops"}'::jsonb, 'The subject has its own room, so the learner ties it to that room.', 'Offer "Only in the school workshop" next to the right answer and ask the question again in a new context.', 'List what a family does in one week (repairing, measuring, budgeting, using a phone safely) and name the strand for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO.M_PT7_PI_STRAND_OTHER', 'PRET.G7.FOUNDA.INTRODUCTION_TO_PRE_TECH.PT_INTRO', 'Thinks budgeting or using a computer belongs to another subject, not to Pre-Technical Studies.', '{"question":"Preparing a budget for a school club belongs to which strand of Pre-Technical Studies?","wrong_answer":"None, it is only Mathematics","correct_answer":"Entrepreneurship"}'::jsonb, 'Money sums are done in Mathematics, so the learner does not expect them here.', 'Offer "None, it is only Mathematics" beside "Entrepreneurship" and ask the child to choose.', 'Read the five strand names (Foundations, Communication, Materials for Production, Tools and Production, Entrepreneurship) and place budgeting and computer use in them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS.M_ST_SLIP_TRIP', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS', 'Treats a slip and a trip as the same thing.', '{"question":"Kamau steps on a wet floor and his feet slide away. What is this?","wrong_answer":"A trip","correct_answer":"A slip"}'::jsonb, 'Both words describe falling over, and they are used loosely at home.', 'Offer "A trip" next to the right answer and ask the question again in a new context.', 'A slip is sliding on a smooth or wet surface; a trip is catching the foot on something.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS.M_ST_FIRE_STOVE', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS', 'Thinks fires start only from big flames, not from wires, chargers or cooking oil.', '{"question":"Which can start a fire?","wrong_answer":"Only a big open flame","correct_answer":"A faulty wire, an overloaded socket or hot cooking oil"}'::jsonb, 'The learner pictures fire as a bonfire or a burning house, not as a charger or a pan.', 'Offer "Only a big open flame" next to the right answer and ask the question again in a new context.', 'List five ways a fire can start in a house or a workshop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS.M_ST_DEVICE_THIEF', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS', 'Thinks the only threat to a phone or computer is a thief.', '{"question":"Which can harm a computer?","wrong_answer":"Only a thief","correct_answer":"A thief, a flood or fire, or a hardware fault"}'::jsonb, 'Theft is the threat people talk about most, so floods, fire and hardware faults are forgotten.', 'Offer "Only a thief" next to the right answer and ask the question again in a new context.', 'Ask what happens to a computer in a flood, in lightning or when the power surges.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS.M_ST_ROAD_DRIVER', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_THREATS', 'Thinks road crashes only harm drivers on highways.', '{"question":"Who is at risk from road crashes?","wrong_answer":"Only drivers on highways","correct_answer":"Pedestrians, cyclists, boda boda riders, passengers and drivers"}'::jsonb, 'News pictures of highway crashes make the learner think only of drivers.', 'Offer "Only drivers on highways" next to the right answer and ask the question again in a new context.', 'List who is on a road outside the school gate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE.M_SO_LOOKS_REAL', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'Thinks a message is safe if it looks like it comes from a bank or M-Pesa.', '{"question":"A message that looks like M-Pesa asks you to send your PIN. What is it?","wrong_answer":"A real message, because it looks official","correct_answer":"Phishing, a trick to get your PIN"}'::jsonb, 'A logo and good spelling feel like proof that a message is real.', 'Offer "A real message, because it looks official" next to the right answer and ask the question again in a new context.', 'Show that anybody can copy a logo. Real companies never ask for a PIN.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE.M_SO_ACCEPT_STRANGER', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'Thinks it is fine to accept a friend request from someone met only online.', '{"question":"A stranger sends you a friend request. What should you do?","wrong_answer":"Accept, because more friends is better","correct_answer":"Not accept, and tell a trusted adult"}'::jsonb, 'Many friends online feels like being popular, so every request seems good.', 'Offer "Accept, because more friends is better" next to the right answer and ask the question again in a new context.', 'Ask: would you give a stranger at the gate your home address?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE.M_SO_BULLY_JOKE', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'Thinks cyberbullying is only a joke because nobody is hit.', '{"question":"Is hurting someone with nasty messages harmful?","wrong_answer":"No, words online do not hurt","correct_answer":"Yes, it is cyberbullying and it hurts"}'::jsonb, 'Nobody is hit, so the learner does not see the hurt.', 'Offer "No, words online do not hurt" next to the right answer and ask the question again in a new context.', 'Ask how a nasty message to you would feel; a message can be kept and shared.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE.M_SO_IMPERSONATE', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'Thinks impersonation means using a nickname.', '{"question":"Someone makes an account with your friend''s name and photo. What is this?","wrong_answer":"A nickname","correct_answer":"Impersonation"}'::jsonb, 'A nickname and a fake account both use a changed name.', 'Offer "A nickname" next to the right answer and ask the question again in a new context.', 'A nickname is open and harmless; impersonation pretends to be a real person to trick others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE.M_SO_HACK_EXPERT', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_ONLINE', 'Thinks hacking happens only to banks and never to a child''s phone or account.', '{"question":"Who can be hacked?","wrong_answer":"Only banks and big companies","correct_answer":"Anyone with a weak password or a careless click"}'::jsonb, 'The learner only hears of hacking in news about banks and companies.', 'Offer "Only banks and big companies" next to the right answer and ask the question again in a new context.', 'Ask what a thief would want from a child''s social media account.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES.M_SR_RUSH', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'Thinks working fast is safer or better in a workshop.', '{"question":"Which habit keeps you safe in the workshop?","wrong_answer":"Work as quickly as possible","correct_answer":"Work carefully and follow the steps"}'::jsonb, 'Speed looks like skill, and finishing first is praised in class.', 'Offer "Work as quickly as possible" next to the right answer and ask the question again in a new context.', 'Ask what happens to a hand that hurries near a saw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES.M_SR_NO_REPORT', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'Thinks a small cut or a near miss need not be reported.', '{"question":"You cut your finger a little. What should you do?","wrong_answer":"Say nothing, it is small","correct_answer":"Tell the teacher and clean the cut"}'::jsonb, 'The learner fears being punished or thinks a small cut does not count.', 'Offer "Say nothing, it is small" next to the right answer and ask the question again in a new context.', 'A cut can be dirty; the teacher can also fix what caused it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES.M_SR_LOOSE', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'Thinks long hair or loose clothes do no harm near a machine.', '{"question":"What should you do with long hair in the workshop?","wrong_answer":"Leave it loose","correct_answer":"Tie it back"}'::jsonb, 'The learner has never seen hair or a sleeve caught in a turning machine.', 'Offer "Leave it loose" next to the right answer and ask the question again in a new context.', 'Show how a loose sleeve could be caught by a moving part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES.M_SR_TOOLS_FLOOR', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'Thinks tools can be left anywhere on the floor or bench.', '{"question":"Where do tools go when the job is done?","wrong_answer":"Anywhere, on the floor is fine","correct_answer":"Back in their place, cleaned"}'::jsonb, 'The learner sees a tool on the floor as untidy, not as something to trip on or a blade to step on.', 'Offer "Anywhere, on the floor is fine" next to the right answer and ask the question again in a new context.', 'Ask who might step on a tool left in a walkway.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES.M_PT7_SR_HORSEPLAY', 'PRET.G7.FOUNDA.SAFETY_IN_THE_IMMEDIATE_.SAFETY_RULES', 'Thinks playing or running in the workshop is fine when no machine is on.', '{"question":"Two learners chase each other in the workshop while the teacher is out. What is wrong?","wrong_answer":"Nothing, no machine is running","correct_answer":"Running and playing cause falls, cuts and knocked tools, at any time"}'::jsonb, 'The learner links danger only with machines that are switched on.', 'Offer "Nothing, no machine is running" beside "Running and playing cause falls, cuts and knocked tools, at any time" and ask the child to choose.', 'List what is in the workshop even with machines off (sharp tools, heavy vices, benches, edges) and agree the rule: walk, never play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS.M_CC_DATA_INFO', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'Thinks data and information are the same.', '{"question":"A list of marks 45, 62, 38 is data. What is the class average?","wrong_answer":"Data too, they are the same thing","correct_answer":"Information, because the data was processed"}'::jsonb, 'In daily talk "data" and "information" mean the same thing.', 'Offer "Data too, they are the same thing" next to the right answer and ask the question again in a new context.', 'Give raw marks (data), then work out the average together (information). Sort ten examples into data and information.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS.M_CC_ALWAYS_RIGHT', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'Thinks a computer is accurate even when the person types the wrong thing in.', '{"question":"A clerk types a wrong price. What will the computer print?","wrong_answer":"The right price, computers never make mistakes","correct_answer":"The wrong price, from wrong input"}'::jsonb, 'Accurate is heard as "always right", so the learner forgets the person typing.', 'Offer "The right price, computers never make mistakes" next to the right answer and ask the question again in a new context.', 'Teach "garbage in, garbage out": type a wrong price on purpose and print the receipt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS.M_CC_TIRED', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'Thinks diligence means a computer gets tired and must rest like a person.', '{"question":"What does diligence mean for a computer?","wrong_answer":"It gets tired and needs rest","correct_answer":"It can work for long hours without getting tired"}'::jsonb, 'Diligence is a word used for hard-working people, who get tired.', 'Offer "It gets tired and needs rest" next to the right answer and ask the question again in a new context.', 'Say diligence means working for long hours without getting tired or bored; compare a cashier at the end of the day with a till.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS.M_CC_THINKS', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'Thinks a computer thinks and decides by itself.', '{"question":"How does a computer know what to do?","wrong_answer":"It thinks for itself","correct_answer":"It follows instructions given to it"}'::jsonb, 'Films and adverts show clever talking machines.', 'Offer "It thinks for itself" next to the right answer and ask the question again in a new context.', 'Follow a short program step by step on paper; show that the computer only follows the instructions given.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS.M_CC_ONE_JOB', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CHARS', 'Thinks a computer can do only one kind of job.', '{"question":"Which characteristic means a computer can do many kinds of jobs?","wrong_answer":"Diligence","correct_answer":"Versatility"}'::jsonb, 'The learner has not met the word versatility and guesses a word they know.', 'Offer "Diligence" next to the right answer and ask the question again in a new context.', 'Show one computer doing a letter, a game, a calculation and a video call; name the characteristic versatility.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY.M_CL_PHONE_NOT', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY', 'Thinks a smartphone is not a computer.', '{"question":"Is a smartphone a computer?","wrong_answer":"No, only a desktop is","correct_answer":"Yes, it is a micro computer"}'::jsonb, 'The learner links a computer with a big screen, a keyboard and a desk.', 'Offer "No, only a desktop is" next to the right answer and ask the question again in a new context.', 'List what a smartphone does (input, processing, storage, output) and compare with a desktop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY.M_CL_MICRO_SMALL', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY', 'Mixes up the sizes: thinks mini and micro computers are the biggest.', '{"question":"Which is the biggest and most powerful type?","wrong_answer":"Micro computer","correct_answer":"Super computer"}'::jsonb, 'The names do not show the order of size, so the learner guesses.', 'Offer "Micro computer" next to the right answer and ask the question again in a new context.', 'Put the four on a size ladder (super, mainframe, mini, micro) with a picture and an example use each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY.M_CL_ANALOGUE_OLD', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY', 'Thinks an analogue computer is just an old computer or not a computer at all.', '{"question":"What does an analogue computer work with?","wrong_answer":"Only old data","correct_answer":"Continuous measurements such as temperature or speed"}'::jsonb, '"Analogue" sounds like old-fashioned, as in an old clock or radio.', 'Offer "Only old data" next to the right answer and ask the question again in a new context.', 'Compare a car speedometer needle (continuous) with a digital count; analogue computers measure continuous quantities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY.M_CL_SPECIAL_WEAK', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_CLASSIFY', 'Thinks special purpose means weak or low quality.', '{"question":"A computer in a washing machine does only one job. What type is it?","wrong_answer":"A weak general-purpose computer","correct_answer":"A special-purpose computer"}'::jsonb, '"Special" sounds like a cheaper version in the learner''s mind.', 'Offer "A weak general-purpose computer" next to the right answer and ask the question again in a new context.', 'List computers that do one job (washing machine, ATM, traffic light) and say they are built for that job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE.M_PT7_CU_SWITCH_OFF', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE', 'Switches a desktop computer off at the wall socket without shutting it down from the operating system.', '{"question":"You have finished working on a desktop computer. What do you do first?","wrong_answer":"Switch it off at the wall socket","correct_answer":"Save, close the programs, then choose Shut down"}'::jsonb, 'Lights, radios and televisions are switched off at the socket, so a computer seems the same.', 'Offer "Switch it off at the wall socket" beside "Save, close the programs, then choose Shut down" and ask the child to choose.', 'Show the Start menu and Shut down; explain that the computer must close its files first, or work and files can be lost or damaged.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE.M_PT7_CU_NO_SAVE', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE', 'Thinks typed work is kept automatically when a program is closed without saving.', '{"question":"You type a letter and close the program without saving. What happens to the new work?","wrong_answer":"It is kept automatically","correct_answer":"It may be lost, because it was never saved"}'::jsonb, 'Phone apps keep messages and notes by themselves, so the learner expects every program to do the same.', 'Offer "It is kept automatically" beside "It may be lost, because it was never saved" and ask the child to choose.', 'Type one line, close without saving on purpose, reopen the file and see it gone. Then save and repeat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE.M_PT7_CU_SAVE_NAME', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE', 'Accepts the computer''s suggested name (Document1) and folder, so the file cannot be found later.', '{"question":"What should you do when you save a file for the first time?","wrong_answer":"Click Save and keep the name Document1","correct_answer":"Give it a clear name and choose the folder"}'::jsonb, 'The learner wants to finish quickly and does not picture looking for the file next week.', 'Offer "Click Save and keep the name Document1" beside "Give it a clear name and choose the folder" and ask the child to choose.', 'Ask the class to find "Document1" among twenty files with the same name. Then name files like "Kamau budget Term 1".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE.M_PT7_CU_DOUBLE', 'PRET.G7.FOUNDA.COMPUTER_CONCEPTS.COMP_USE', 'Single-clicks a desktop icon and waits for the program to open.', '{"question":"How do you open a program from its icon on the desktop with a mouse?","wrong_answer":"Click it once and wait","correct_answer":"Double-click it, or click once and press Enter"}'::jsonb, 'On a phone one tap opens an app, so one click seems enough.', 'Offer "Click it once and wait" beside "Double-click it, or click once and press Enter" and ask the child to choose.', 'Practise: one click selects (the icon turns blue), two quick clicks open. Let the learner see the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE.M_DP_ARTISTS_ONLY', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE', 'Thinks drawing is only for artists.', '{"question":"Who uses drawing at work?","wrong_answer":"Only artists","correct_answer":"Builders, tailors, mechanics, engineers and artists"}'::jsonb, 'Drawing at school happens in art lessons, so the learner links it with artists.', 'Offer "Only artists" next to the right answer and ask the question again in a new context.', 'Show a tailor''s pattern, a house plan and a car manual drawing; name who uses each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE.M_DP_WORDS_BETTER', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE', 'Thinks words always explain a shape better than a drawing.', '{"question":"Why is a drawing useful?","wrong_answer":"It is not, words are always better","correct_answer":"It shows shape and size that words describe badly"}'::jsonb, 'Words are the learner''s main way of explaining, so they feel enough.', 'Offer "It is not, words are always better" next to the right answer and ask the question again in a new context.', 'Ask one learner to describe a bracket in words only while another draws it; compare with a quick sketch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE.M_DP_TECH_PRETTY', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE', 'Thinks a technical drawing is just a prettier drawing.', '{"question":"What is a technical drawing?","wrong_answer":"A beautiful picture for decoration","correct_answer":"An exact drawing with sizes that a worker can follow"}'::jsonb, '"Technical" is heard as fancy or advanced.', 'Offer "A beautiful picture for decoration" next to the right answer and ask the question again in a new context.', 'Put an artistic drawing of a chair beside a technical drawing with sizes; ask which a carpenter could build from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE.M_DP_ART_NO_RULES', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_PURPOSE', 'Thinks artistic drawing needs exact measuring and technical drawing is free.', '{"question":"Which drawing needs exact sizes and rules?","wrong_answer":"An artistic drawing","correct_answer":"A technical drawing"}'::jsonb, 'The learner swaps the two because both are called drawing.', 'Offer "An artistic drawing" next to the right answer and ask the question again in a new context.', 'Make a two-column chart: artistic (expresses feeling, free) and technical (exact sizes, rules, for making).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES.M_DL_HIDDEN_CHAIN', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES', 'Uses the chain line for hidden detail.', '{"question":"Which line shows hidden detail?","wrong_answer":"Chain line","correct_answer":"Dashed line"}'::jsonb, 'Both broken lines look alike from a distance, and the learner remembers only "a broken line".', 'Offer "Chain line" next to the right answer and ask the question again in a new context.', 'Draw both large: short dashes (hidden detail) and long-short-long (centre line). Say "dashes hide, chains centre".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES.M_DL_CENTRE_DASHED', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES', 'Uses the dashed line for the centre of a round part.', '{"question":"Which line marks the centre of a hole?","wrong_answer":"Dashed line","correct_answer":"Chain line"}'::jsonb, 'The learner has learnt "dashed" first and uses it for every broken line.', 'Offer "Dashed line" next to the right answer and ask the question again in a new context.', 'Draw a hole: its hidden edges in dashes and its centre in chain lines, on the same drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES.M_DL_DIM_THICK', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES', 'Draws dimension lines thick.', '{"question":"Which line is used for dimension lines?","wrong_answer":"Thick continuous line","correct_answer":"Thin continuous line"}'::jsonb, 'Thick is taken to mean important, and the size feels important.', 'Offer "Thick continuous line" next to the right answer and ask the question again in a new context.', 'Show that thick lines are only for the object''s outline; everything added (dimension, projection, hatching) is thin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES.M_DL_OUTLINE_THIN', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LINES', 'Draws the outline of an object with a thin line.', '{"question":"Which line draws the outline of an object?","wrong_answer":"Thin continuous line","correct_answer":"Thick continuous line"}'::jsonb, 'The learner draws lightly for fear of mistakes and never firms the outline.', 'Offer "Thin continuous line" next to the right answer and ask the question again in a new context.', 'Draw light construction lines first, then go over the visible outline in thick lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS.M_DS_R_DIAM', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS', 'Mixes up diameter and radius: reads R as diameter.', '{"question":"What does R mean on a drawing?","wrong_answer":"Diameter","correct_answer":"Radius"}'::jsonb, 'Radius and diameter both belong to circles, and the learner holds only one word for "circle size".', 'Offer "Diameter" next to the right answer and ask the question again in a new context.', 'Draw a circle and label R from the centre to the edge and Ø across; write R 20 and Ø 40 for the same circle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS.M_DS_PERP_PARALLEL', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS', 'Reads the perpendicular symbol as parallel.', '{"question":"What does the symbol ⊥ mean?","wrong_answer":"Parallel","correct_answer":"Perpendicular, at a right angle"}'::jsonb, 'Both symbols describe how two lines sit, and both are made of straight strokes.', 'Offer "Parallel" next to the right answer and ask the question again in a new context.', 'Draw ⊥ beside a T-shape and // beside railway lines; the symbol looks like what it means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS.M_DS_ID_OD', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS', 'Mixes up inside diameter and outside diameter.', '{"question":"What does O/D mean?","wrong_answer":"Inside diameter","correct_answer":"Outside diameter"}'::jsonb, 'The letters I and O are read quickly and swapped.', 'Offer "Inside diameter" next to the right answer and ask the question again in a new context.', 'Draw a pipe end: I/D the hole, O/D the outside; "I for inside, O for outside".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS.M_DS_AF_AC', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_SYMBOLS', 'Mixes up across flats and across corners.', '{"question":"What does A/F mean on a nut?","wrong_answer":"Across corners","correct_answer":"Across flats"}'::jsonb, 'Both measure a hexagon, and "across" is in both.', 'Offer "Across corners" next to the right answer and ask the question again in a new context.', 'Draw a nut: A/F from flat side to flat side (the spanner size), A/C from corner to corner (larger).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING.M_PT7_DLT_CURSIVE', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING', 'Writes notes on a technical drawing in joined-up handwriting.', '{"question":"How are notes written on a technical drawing?","wrong_answer":"In neat joined-up handwriting","correct_answer":"In separate, plain capital letters"}'::jsonb, 'Joined handwriting is praised in English lessons, so it seems the neatest choice.', 'Offer "In neat joined-up handwriting" beside "In separate, plain capital letters" and ask the child to choose.', 'Show the same note in joined writing and in printed capitals to someone across the room; ask which they can read. Practise single-stroke capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING.M_PT7_DLT_MIXED', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING', 'Mixes capital and small letters in a note, as in a sentence.', '{"question":"Which title is correctly printed on a drawing?","wrong_answer":"Front Elevation","correct_answer":"FRONT ELEVATION"}'::jsonb, 'In writing, sentences and names begin with a capital and go on in small letters.', 'Offer "Front Elevation" beside "FRONT ELEVATION" and ask the child to choose.', 'Write three titles on the board in mixed case and ask the learner to reprint them all in capitals between guide lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING.M_PT7_DLT_NO_GUIDE', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING', 'Prints without guide lines, so the letters rise, fall and change height.', '{"question":"What keeps all the letters of a note the same height?","wrong_answer":"Writing carefully without any lines","correct_answer":"Two faint guide lines drawn first"}'::jsonb, 'The learner thinks extra lines will spoil a clean sheet.', 'Offer "Writing carefully without any lines" beside "Two faint guide lines drawn first" and ask the child to choose.', 'Draw two faint guide lines 5 mm apart with a sharp pencil; print between them; compare with a line printed without guides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING.M_PT7_DLT_SPACING', 'PRET.G7.COMMUN.INTRODUCTION_TO_DRAWING.DRAW_LETTERING', 'Crowds the words together with no larger gap between words than between letters.', '{"question":"How should the gaps between words compare with the gaps between letters?","wrong_answer":"The same, so the note fits in a short space","correct_answer":"Wider between words than between letters"}'::jsonb, 'The learner wants the note to fit in the box and squeezes it.', 'Offer "The same, so the note fits in a short space" beside "Wider between words than between letters" and ask the child to choose.', 'Print "STEEL PLATE" with no word gap and ask a partner to read it at a glance; then reprint with a clear word gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES.M_SP_RULER', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES', 'Thinks a sketch must be drawn with a ruler.', '{"question":"What is free-hand sketching?","wrong_answer":"Drawing with a ruler and compass","correct_answer":"Drawing by hand without drawing tools"}'::jsonb, 'Neat work at school is drawn with a ruler, so a sketch seems to need one.', 'Offer "Drawing with a ruler and compass" next to the right answer and ask the question again in a new context.', 'Show a quick freehand sketch of a stool made in one minute; explain it is for ideas, before exact drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES.M_SP_PRESS_FIRST', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES', 'Starts a sketch with dark pressed lines.', '{"question":"How should a sketch start?","wrong_answer":"With dark pressed lines","correct_answer":"With light lines you can change"}'::jsonb, 'The learner wants the sketch right the first time.', 'Offer "With dark pressed lines" next to the right answer and ask the question again in a new context.', 'Sketch light lines that can be changed, then darken the right ones; show a pressed wrong line that cannot be removed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES.M_SP_ERASER', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES', 'Thinks a sketch needs constant rubbing out.', '{"question":"What helps a sketch stay tidy?","wrong_answer":"Rub out every line at once","correct_answer":"Light lines, then firm the right ones"}'::jsonb, 'The learner fears wrong lines and rubs out at once.', 'Offer "Rub out every line at once" next to the right answer and ask the question again in a new context.', 'Leave light construction lines; darken only the correct ones; rub out at the end if needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES.M_SP_PROPORTION', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_PRINCIPLES', 'Starts with small details and ignores the overall shape and proportion.', '{"question":"What do you look at first when sketching a bottle?","wrong_answer":"The label detail","correct_answer":"The whole shape and its proportions"}'::jsonb, 'The detail is the most interesting part to look at.', 'Offer "The label detail" next to the right answer and ask the question again in a new context.', 'Block in the whole shape and its proportions with light lines first, then add the details.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES.M_SK_HATCH_DOTS', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'Thinks hatching is drawn with dots.', '{"question":"What is hatching?","wrong_answer":"Shading with dots","correct_answer":"Shading with parallel lines"}'::jsonb, 'Hatching and stippling are both shading and are learnt together.', 'Offer "Shading with dots" next to the right answer and ask the question again in a new context.', 'Shade three squares: hatching (parallel lines), cross-hatching (crossing lines), stippling (dots); label each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES.M_SK_CROSS_HATCH', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'Thinks cross-hatching is one set of lines drawn across the shape.', '{"question":"What is cross-hatching?","wrong_answer":"One set of lines across the shape","correct_answer":"Two sets of lines that cross each other"}'::jsonb, 'The word "cross" is heard as "across the shape".', 'Offer "One set of lines across the shape" next to the right answer and ask the question again in a new context.', 'Draw one set of parallel lines, then a second set crossing them: that is cross-hatching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES.M_SK_BOX_CIRCLE', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'Thinks the box method is for circles only, or mixes it with the hand compass method.', '{"question":"Which method draws a circle with the hand turning about a fixed finger?","wrong_answer":"Box method","correct_answer":"Hand compass method"}'::jsonb, 'Box and compass both sound like ways to make a circle.', 'Offer "Box method" next to the right answer and ask the question again in a new context.', 'Sketch a circle twice: in a light square (box method) and by turning the paper about a fixed finger (hand compass).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES.M_SK_CENTRE_ANY', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'Uses the centreline method for a shape that is not symmetrical.', '{"question":"Which object suits the centreline method?","wrong_answer":"A pile of stones","correct_answer":"A bottle, the same on both sides"}'::jsonb, 'The learner has not linked the centreline method with symmetry.', 'Offer "A pile of stones" next to the right answer and ask the question again in a new context.', 'Draw a centreline, mark equal distances on both sides; try it on a bottle and on a stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES.M_PT7_SK_STROKE_PUSH', 'PRET.G7.COMMUN.FREE_HAND_SKETCHING.SKETCH_TECHNIQUES', 'Sketches long lines with short scratchy strokes pushed away from the body.', '{"question":"How is a long straight line sketched freehand?","wrong_answer":"With many short scratchy strokes","correct_answer":"With light, steady strokes, moving the whole arm, between two marked points"}'::jsonb, 'Short strokes feel easier to control.', 'Offer "With many short scratchy strokes" beside "With light, steady strokes, moving the whole arm, between two marked points" and ask the child to choose.', 'Mark two points, keep the eye on the end point and draw with the whole arm in light strokes; compare with a scratchy line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS.M_IT_ALL_FREE', 'PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'Thinks ICT tools cost nothing to use.', '{"question":"What does a video call need?","wrong_answer":"Nothing, it is free","correct_answer":"Data or an internet link, and a device"}'::jsonb, 'Messages seem to arrive for nothing because the learner does not pay for the data.', 'Offer "Nothing, it is free" next to the right answer and ask the question again in a new context.', 'List what each tool needs (a device, airtime or data, power) and the cost of one hour of video calling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS.M_IT_SMS_NET', 'PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'Thinks a text message (SMS) needs the internet.', '{"question":"Which needs no internet?","wrong_answer":"A text message (SMS)","correct_answer":"A video conference"}'::jsonb, 'The learner links every phone use with data bundles.', 'Offer "A text message (SMS)" next to the right answer and ask the question again in a new context.', 'Switch off mobile data and send an SMS; it still goes. Then try a video call.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS.M_IT_EMAIL_LIVE', 'PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'Thinks email is a live video link.', '{"question":"Which tool lets people see and hear one another live?","wrong_answer":"Email","correct_answer":"Video conferencing"}'::jsonb, 'Email and video calls both run on the internet.', 'Offer "Email" next to the right answer and ask the question again in a new context.', 'Sort tools into live (phone call, video conference) and not live (email, SMS).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS.M_IT_SOCIAL_FUN', 'PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'Thinks social networking is only for fun and never for work or learning.', '{"question":"How can social networking help a small business?","wrong_answer":"It cannot","correct_answer":"It shows products to many customers"}'::jsonb, 'The learner sees social media used mostly for chat and games.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Show a small business page selling mandazi or tailoring on a social network; list three uses for work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS.M_PT7_IT_PICK_TOOL', 'PRET.G7.COMMUN.ICT_TOOLS_IN_COMMUNICATI.ICT_TOOLS', 'Picks a tool that does not suit the message, such as an SMS to send a drawing to a fundi.', '{"question":"You must send a drawing of a shelf to a fundi far away. Which tool suits it best?","wrong_answer":"An SMS text message","correct_answer":"Email or a messaging app that sends pictures"}'::jsonb, 'The learner uses the tool they use most, whatever the message.', 'Offer "An SMS text message" beside "Email or a messaging app that sends pictures" and ask the child to choose.', 'Give five messages (a drawing, an urgent warning, a meeting) and choose the tool for each, saying why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL.M_MM_SHINY', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL', 'Thinks anything shiny is a metal.', '{"question":"Which of these is non-metallic?","wrong_answer":"Glass, even though it shines","correct_answer":"Steel"}'::jsonb, 'Shine is the first thing the learner links with metal.', 'Offer "Glass, even though it shines" next to the right answer and ask the question again in a new context.', 'Put glass, a polished tile and a steel spoon side by side; test each with heat or a magnet and sort them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL.M_MM_HARD_METAL', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL', 'Thinks anything hard or heavy is a metal.', '{"question":"Which of these is non-metallic?","wrong_answer":"Stone, because it is hard","correct_answer":"Copper"}'::jsonb, 'Hard and heavy objects feel like metal in the hand.', 'Offer "Stone, because it is hard" next to the right answer and ask the question again in a new context.', 'Compare a stone and a copper wire: the stone is hard but breaks, does not conduct; the copper bends and conducts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL.M_MM_PRODUCT', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL', 'Treats a finished product as a material.', '{"question":"Which of these is a material?","wrong_answer":"A chair","correct_answer":"Wood"}'::jsonb, 'The learner names the thing, not what it is made of.', 'Offer "A chair" next to the right answer and ask the question again in a new context.', 'Ask "what is it made of?" for ten objects; write the material, not the object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE.M_MS_WASTE_OK', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE', 'Thinks there is no need to save materials that are plentiful.', '{"question":"A carpenter has plenty of timber. What is a good habit?","wrong_answer":"Waste it, there is plenty","correct_answer":"Plan the cuts and use offcuts"}'::jsonb, 'Plenty now feels like plenty for ever.', 'Offer "Waste it, there is plenty" next to the right answer and ask the question again in a new context.', 'Show how much timber one tree gives and how long it takes to grow; plan cuts on paper to use offcuts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE.M_MS_BURN_OFFCUTS', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE', 'Thinks burning scrap is the best way to get rid of it.', '{"question":"What is a better use of scrap metal?","wrong_answer":"Burn it","correct_answer":"Recycle it"}'::jsonb, 'The learner wants the scrap out of the way as fast as possible.', 'Offer "Burn it" next to the right answer and ask the question again in a new context.', 'List scrap that can be sold, recycled or reused (scrap metal dealers, offcuts for small items); say what burning releases.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE.M_MS_NEW_ONLY', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE', 'Thinks new materials are always better than reusing old ones.', '{"question":"A worn chair leg can be repaired. What is sustainable?","wrong_answer":"Throw it away and buy new","correct_answer":"Repair and reuse it"}'::jsonb, 'New things look better and repair seems like poverty.', 'Offer "Throw it away and buy new" next to the right answer and ask the question again in a new context.', 'Repair a chair leg in class; compare the cost and material used with buying a new chair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL.M_PT7_MM_FACTORY_METAL', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_METAL_NONMETAL', 'Thinks any factory-made material is metallic, so puts a plastic pipe with the metals.', '{"question":"Which of these is a metallic material?","wrong_answer":"A plastic water pipe, because it is made in a factory","correct_answer":"An iron sheet"}'::jsonb, 'Metals and plastics are both bought in hardware shops, so made in a factory sounds like metal.', 'Offer "A plastic water pipe, because it is made in a factory" beside "An iron sheet" and ask the child to choose.', 'Sort hardware-shop items by testing: does it conduct heat? Does it bend without breaking? Does it ring when tapped?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE.M_PT7_MS_CHEAP_LASTS', 'PRET.G7.MATERI.INTRODUCTION_TO_MATERIAL.MAT_SUSTAINABLE', 'Thinks the cheapest material is the sustainable choice, even when it wears out fast.', '{"question":"A carpenter can buy cheap timber that rots in a year, or treated timber that lasts ten years. Which is more sustainable?","wrong_answer":"The cheap timber, because it costs less now","correct_answer":"The treated timber, because it lasts and saves material"}'::jsonb, 'Low cost today feels like saving.', 'Offer "The cheap timber, because it costs less now" beside "The treated timber, because it lasts and saves material" and ask the child to choose.', 'Count how many cheap posts are needed in ten years against one treated post; add up the cost and the trees used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES.M_MT_ALU_STEEL', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES', 'Thinks aluminium is a kind of steel and sticks to a magnet.', '{"question":"A silvery, light metal does not stick to a magnet. What is it likely to be?","wrong_answer":"Steel","correct_answer":"Aluminium"}'::jsonb, 'Both are grey-silver and the learner sorts by colour only.', 'Offer "Steel" next to the right answer and ask the question again in a new context.', 'Test a steel nail and an aluminium can with a magnet and by weight in the hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES.M_MT_COPPER_COLOUR', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES', 'Does not know copper is reddish-brown.', '{"question":"Which metal is reddish-brown?","wrong_answer":"Aluminium","correct_answer":"Copper"}'::jsonb, 'Most metals the learner sees are grey, so copper is not recognised.', 'Offer "Aluminium" next to the right answer and ask the question again in a new context.', 'Strip a piece of electric cable and show the reddish-brown copper inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES.M_MT_MAGNET_ALL', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES', 'Thinks a magnet picks up every metal.', '{"question":"A magnet does not pick up a metal spoon. What can you say?","wrong_answer":"It cannot be metal","correct_answer":"It may be aluminium or copper"}'::jsonb, 'Only iron and steel objects are tested with magnets at home and school.', 'Offer "It cannot be metal" next to the right answer and ask the question again in a new context.', 'Test a nail, a copper wire, an aluminium can and a brass key with a magnet; only the nail sticks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES.M_MP_ALL_MAGNETIC', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES', 'Thinks all metals are magnetic.', '{"question":"Which metal does a magnet pick up?","wrong_answer":"Copper","correct_answer":"Steel"}'::jsonb, 'The only magnet test the learner has seen used a nail or pins.', 'Offer "Copper" next to the right answer and ask the question again in a new context.', 'Test five metals with a magnet and record which stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES.M_MP_ALL_RUST', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES', 'Thinks every metal rusts.', '{"question":"Which metal rusts?","wrong_answer":"Copper and aluminium as well","correct_answer":"Iron and steel"}'::jsonb, '"Rust" is used at home for any old, dull metal.', 'Offer "Copper and aluminium as well" next to the right answer and ask the question again in a new context.', 'Show a rusty nail, green old copper and a dull aluminium pot; only iron and steel rust (red-brown).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES.M_MP_NO_HEAT', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES', 'Thinks metals do not conduct heat.', '{"question":"Why does a metal spoon get hot in hot tea?","wrong_answer":"Metals do not carry heat","correct_answer":"Metals conduct heat well"}'::jsonb, 'Pan handles are plastic or wood, so the learner thinks metal keeps heat in.', 'Offer "Metals do not carry heat" next to the right answer and ask the question again in a new context.', 'Put a metal and a plastic spoon in hot water and feel the handles after a minute (with care).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES.M_MP_BRITTLE', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_PROPERTIES', 'Thinks metals shatter when hammered, like glass.', '{"question":"What happens when copper is hammered?","wrong_answer":"It shatters","correct_answer":"It can be shaped into a sheet or drawn into wire"}'::jsonb, 'The learner compares all hard materials with glass.', 'Offer "It shatters" next to the right answer and ask the question again in a new context.', 'Hammer a short copper wire flat and bend it; compare with a piece of tile (shown, not done by learners).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES.M_MU_WIRE_STEEL', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES', 'Thinks electric wire is made of steel.', '{"question":"Which metal makes electric wire?","wrong_answer":"Steel","correct_answer":"Copper"}'::jsonb, 'Steel is the metal the learner knows best.', 'Offer "Steel" next to the right answer and ask the question again in a new context.', 'Strip a cable and show copper; say copper conducts electricity very well and bends easily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES.M_MU_ALU_HEAVY', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES', 'Thinks aluminium is heavy and chosen for strength.', '{"question":"Why is a sufuria often made of aluminium?","wrong_answer":"It is very heavy","correct_answer":"It is light and conducts heat"}'::jsonb, 'Strong and heavy are linked in the learner''s mind.', 'Offer "It is very heavy" next to the right answer and ask the question again in a new context.', 'Weigh an aluminium sufuria and a steel one of the same size; aluminium is light and conducts heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES.M_MU_PROPERTY_SWAP', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES', 'Matches a use to a property that does not fit.', '{"question":"Why is steel used for a jembe blade?","wrong_answer":"Because it does not conduct heat","correct_answer":"Because it is hard and strong"}'::jsonb, 'The learner guesses a reason without checking the property against the job.', 'Offer "Because it does not conduct heat" next to the right answer and ask the question again in a new context.', 'For each use, ask "what must the metal do here?" then pick the property.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES.M_PT7_MT_FERROUS', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_TYPES', 'Thinks ferrous means any strong or hard metal, so calls aluminium ferrous.', '{"question":"Which metal is ferrous (contains iron)?","wrong_answer":"Aluminium, because it is a strong metal","correct_answer":"Mild steel"}'::jsonb, 'The learner meets "ferrous" as a new word and guesses it means strong.', 'Offer "Aluminium, because it is a strong metal" beside "Mild steel" and ask the child to choose.', 'Teach ferrous = contains iron (iron, steel); non-ferrous = no iron (copper, aluminium, zinc, lead, tin). Test with a magnet and rust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES.M_PT7_MU_GALVANISE', 'PRET.G7.MATERI.METALLIC_MATERIALS.METAL_USES', 'Thinks iron roofing sheets are coated with zinc (galvanised) to make them shine.', '{"question":"Why are iron roofing sheets galvanised (coated with zinc)?","wrong_answer":"To make them shine","correct_answer":"To stop them rusting"}'::jsonb, 'New iron sheets are shiny, so the learner thinks the coating is for looks.', 'Offer "To make them shine" beside "To stop them rusting" and ask the child to choose.', 'Show a new and an old roofing sheet; rust starts where the zinc coat is scratched. Name galvanising.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS.M_NC_SYNTH_FAKE', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS', 'Thinks synthetic means fake or poor quality.', '{"question":"What does synthetic mean?","wrong_answer":"Fake","correct_answer":"Made by people from chemicals"}'::jsonb, '"Synthetic" is used for imitation hair and fake leather.', 'Offer "Fake" next to the right answer and ask the question again in a new context.', 'Say synthetic means made by people from chemicals (often from oil): nylon, polythene, PVC. It can be very strong.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS.M_NC_NATURAL_UNMADE', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS', 'Thinks natural means a material can never be shaped by people.', '{"question":"Is wood still natural when made into a table?","wrong_answer":"No, people changed it","correct_answer":"Yes, it comes from a tree"}'::jsonb, 'The learner confuses natural with untouched.', 'Offer "No, people changed it" next to the right answer and ask the question again in a new context.', 'Trace a table back to a tree; the material is still wood, a natural material, even when shaped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS.M_NC_PLASTIC_NATURAL', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS', 'Thinks plastic is a natural material.', '{"question":"Which is synthetic?","wrong_answer":"Cotton","correct_answer":"A polythene bag"}'::jsonb, 'Plastic is everywhere around the learner, so it feels like part of nature.', 'Offer "Cotton" next to the right answer and ask the question again in a new context.', 'Trace a polythene bag back to oil and a factory; trace cotton back to a plant.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS.M_NC_WOOL_SYNTH', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_CLASS', 'Thinks nylon cloth is natural like cotton.', '{"question":"Which cloth fibre is synthetic?","wrong_answer":"Wool","correct_answer":"Nylon"}'::jsonb, 'Both are fabrics, and the learner sorts by use, not source.', 'Offer "Wool" next to the right answer and ask the question again in a new context.', 'Burn-test is not done; instead read clothing labels and trace each fibre to a plant, an animal or a factory.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES.M_NP_ALL_BURN', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES', 'Thinks all non-metals burn.', '{"question":"Which non-metal does not burn?","wrong_answer":"Wood","correct_answer":"A clay brick"}'::jsonb, 'Wood and paper burn, and the learner lumps all non-metals with them.', 'Offer "Wood" next to the right answer and ask the question again in a new context.', 'Show (do not test) that clay bricks and stone are fired or formed by great heat; they do not burn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES.M_NP_PLASTIC_HEAT', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES', 'Thinks plastics stand up to heat like metals.', '{"question":"What happens to a plastic basin on a hot jiko?","wrong_answer":"Nothing, plastic is heat-proof","correct_answer":"It softens and melts"}'::jsonb, 'The learner has not seen plastic melt and trusts its hardness.', 'Offer "Nothing, plastic is heat-proof" next to the right answer and ask the question again in a new context.', 'Show a picture of a plastic basin melted by a jiko; say plastics soften with heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES.M_NP_HARD_UNBREAKABLE', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES', 'Thinks that hard means it cannot break.', '{"question":"Glass is hard. Can it break?","wrong_answer":"No, hard materials never break","correct_answer":"Yes, glass is hard but brittle"}'::jsonb, 'Hard and strong are treated as the same word.', 'Offer "No, hard materials never break" next to the right answer and ask the question again in a new context.', 'Compare a glass marble (hard, breaks) with a rubber ball (soft, does not break): hard is not the same as tough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES.M_NP_RUBBER_CONDUCT', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_PROPERTIES', 'Thinks rubber carries electricity.', '{"question":"Why do electricians wear rubber gloves?","wrong_answer":"Rubber carries electricity","correct_answer":"Rubber does not carry electricity"}'::jsonb, 'The learner has not met the idea of an insulator.', 'Offer "Rubber carries electricity" next to the right answer and ask the question again in a new context.', 'Show a cable: copper inside carries electricity, rubber or plastic outside stops it. Name insulator.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES.M_NU_GLASS_HANDLE', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES', 'Picks a material whose property does not fit the use.', '{"question":"Which material suits a water tank?","wrong_answer":"Glass","correct_answer":"Plastic"}'::jsonb, 'The learner picks a familiar material without checking it against the job.', 'Offer "Glass" next to the right answer and ask the question again in a new context.', 'Ask "what must a water tank do?" (hold water, not break, be light) and test each material against it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES.M_NU_WOOD_ANY', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES', 'Thinks wood suits every job.', '{"question":"Which material suits a floor tile in a kitchen?","wrong_answer":"Wood, because it is natural","correct_answer":"Ceramic, because it is hard and does not burn"}'::jsonb, 'Wood is the first material that comes to mind for making things.', 'Offer "Wood, because it is natural" next to the right answer and ask the question again in a new context.', 'For a kitchen floor, list what it must do (not burn, easy to clean, hard); compare wood and ceramic tiles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES.M_NU_CEMENT', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES', 'Thinks cement is the finished wall, not the binder.', '{"question":"What does cement do in a wall?","wrong_answer":"It is the wall","correct_answer":"It joins the blocks as it sets"}'::jsonb, 'Cement and concrete are used as one word in daily talk.', 'Offer "It is the wall" next to the right answer and ask the question again in a new context.', 'Show cement powder, then a block joined with mortar; cement is the binder that sets and holds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES.M_PT7_NU_GLASS_STRONG', 'PRET.G7.MATERI.NON_METALLIC_MATERIALS.NONMETAL_USES', 'Thinks glass is used for windows because it is the strongest material.', '{"question":"Why is glass used for windows?","wrong_answer":"Because it is the strongest material","correct_answer":"Because it lets light through and keeps out wind and rain"}'::jsonb, 'Windows feel important, so the learner thinks the material must be strong.', 'Offer "Because it is the strongest material" beside "Because it lets light through and keeps out wind and rain" and ask the child to choose.', 'Ask what a window must do (let light in, keep weather out); glass is transparent, but it breaks easily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS.M_MV_VOLT_AMP', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS', 'Thinks a voltmeter measures current.', '{"question":"Which tool measures voltage?","wrong_answer":"Ammeter","correct_answer":"Voltmeter"}'::jsonb, 'Both meters have a dial and a needle and are named after units the learner has just met.', 'Offer "Ammeter" next to the right answer and ask the question again in a new context.', 'Write volt = voltmeter, ampere = ammeter; match each unit to its meter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS.M_MV_BALANCE_LEN', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS', 'Thinks a weighing balance measures length.', '{"question":"What does a weighing balance measure?","wrong_answer":"Length","correct_answer":"Mass"}'::jsonb, 'The learner calls every tool a "measuring tool" without asking what it measures.', 'Offer "Length" next to the right answer and ask the question again in a new context.', 'Make a table: tool, what it measures, unit (balance, mass, kg or g).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS.M_MV_STOPWATCH', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS', 'Thinks a stopwatch measures speed or length.', '{"question":"What does a stopwatch measure?","wrong_answer":"Speed","correct_answer":"Time"}'::jsonb, 'The learner has seen stopwatches at races, where speed is the point.', 'Offer "Speed" next to the right answer and ask the question again in a new context.', 'Time a learner walking 10 m: the stopwatch gives seconds; speed needs distance as well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS.M_MV_RULER_ALL', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MEAS_TOOLS', 'Thinks a steel rule is best for every length.', '{"question":"Which tool measures the length of a long wall?","wrong_answer":"Steel rule","correct_answer":"Tape measure"}'::jsonb, 'The steel rule is the tool the learner knows best.', 'Offer "Steel rule" next to the right answer and ask the question again in a new context.', 'Try to measure the classroom wall with a 30 cm rule, then with a tape; compare time and accuracy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS.M_MK_PUNCH_HOLE', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS', 'Thinks a dot punch makes a hole.', '{"question":"What does a dot punch do?","wrong_answer":"Makes the hole","correct_answer":"Makes a small dent to mark a centre"}'::jsonb, '"Punch" sounds like a tool that goes right through.', 'Offer "Makes the hole" next to the right answer and ask the question again in a new context.', 'The dent guides the drill bit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS.M_MK_DIVIDER_CUT', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS', 'Thinks a divider cuts metal.', '{"question":"What is a divider used for?","wrong_answer":"Cutting metal","correct_answer":"Marking circles and arcs"}'::jsonb, 'Dividers have two sharp legs and look like scissors.', 'Offer "Cutting metal" next to the right answer and ask the question again in a new context.', 'Scribe an arc on a scrap plate with dividers; show they mark, never cut.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS.M_MK_SQUARE_LENGTH', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS', 'Thinks a try-square measures length.', '{"question":"What does a try-square check?","wrong_answer":"The length of a board","correct_answer":"A right angle"}'::jsonb, 'The blade of a try-square looks like a ruler.', 'Offer "The length of a board" next to the right answer and ask the question again in a new context.', 'Check the corner of a book and a board with the try-square; it tests a right angle, not a length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS.M_MK_PENCIL_METAL', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.MARK_TOOLS', 'Thinks a pencil is the right tool for marking steel.', '{"question":"Which tool marks a fine line on steel?","wrong_answer":"Pencil","correct_answer":"Scriber"}'::jsonb, 'A pencil is the usual marker at school.', 'Offer "Pencil" next to the right answer and ask the question again in a new context.', 'Mark steel with a pencil and with a scriber, then wipe both; only the scribed line stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE.M_TC_TAPE_ALL', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'Uses a tape measure for everything.', '{"question":"Which tool measures the diameter of a bolt most exactly?","wrong_answer":"Tape measure","correct_answer":"Callipers"}'::jsonb, 'The tape measure is the tool the learner has used most.', 'Offer "Tape measure" next to the right answer and ask the question again in a new context.', 'Measure a bolt with a tape and with callipers; compare how exact each reading is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE.M_TC_NEAREST', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'Picks any tool that is close to hand.', '{"question":"You need a right angle on a board. What do you pick?","wrong_answer":"Whatever is nearest","correct_answer":"A try-square"}'::jsonb, 'Convenience feels more important than the right tool.', 'Offer "Whatever is nearest" next to the right answer and ask the question again in a new context.', 'Role-play a fundi job: pick the tool for each step and say why; the nearest tool gives a wrong mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE.M_TC_PRECISION', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'Thinks accuracy does not depend on the tool.', '{"question":"Why use a scriber rather than a pencil on steel?","wrong_answer":"No reason, both are the same","correct_answer":"It gives a finer line that lasts"}'::jsonb, 'The learner thinks a mark is a mark, whatever made it.', 'Offer "No reason, both are the same" next to the right answer and ask the question again in a new context.', 'Compare a pencil line and a scribed line on steel under a magnifier; the scribed line is finer and stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE.M_CT_NO_OIL', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE', 'Thinks a wet steel tool can be put away without drying.', '{"question":"What do you do to a steel tool after use?","wrong_answer":"Put it away wet","correct_answer":"Wipe it dry and oil it lightly"}'::jsonb, 'Rust does not appear at once, so the learner does not link it with putting tools away wet.', 'Offer "Put it away wet" next to the right answer and ask the question again in a new context.', 'Leave one wet and one oiled steel offcut for a week and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE.M_CT_HAMMER', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE', 'Uses a steel rule or try-square as a lever or hammer.', '{"question":"What should you not do with a steel rule?","wrong_answer":"Nothing, it is strong","correct_answer":"Use it as a lever or hammer"}'::jsonb, 'Steel feels too tough to be harmed.', 'Offer "Nothing, it is strong" next to the right answer and ask the question again in a new context.', 'Show a bent steel rule whose scale is now wrong; a tool used as a lever or hammer loses its accuracy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE.M_CT_HEAP', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE', 'Throws tools into a heap after use.', '{"question":"Where do tools go at the end of the lesson?","wrong_answer":"In a heap in the box","correct_answer":"In their place, clean and dry"}'::jsonb, 'Tidying is rushed at the end of the lesson.', 'Offer "In a heap in the box" next to the right answer and ask the question again in a new context.', 'Use a shadow board: each tool has its outline; a missing or misplaced tool is seen at once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE.M_CT_POINTS_OPEN', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CARE', 'Leaves the points of dividers and scribers uncovered.', '{"question":"How do you store a scriber or divider?","wrong_answer":"With the sharp point uncovered","correct_answer":"With the point covered or in a holder"}'::jsonb, 'The learner sees a sharp point as useful, not as a danger to hands in the tool box.', 'Offer "With the sharp point uncovered" next to the right answer and ask the question again in a new context.', 'A point can hurt a hand and be blunted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE.M_PT7_TU_RULE_END', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE', 'Measures from the end of a ruler that has a margin before its zero mark.', '{"question":"A ruler has a small gap before the 0 mark. Where do you start measuring?","wrong_answer":"At the end of the ruler","correct_answer":"At the 0 mark"}'::jsonb, 'On a steel rule the end is the zero, so every ruler seems the same.', 'Offer "At the end of the ruler" beside "At the 0 mark" and ask the child to choose.', 'Measure the same line from the end and from the 0 mark; compare the two readings and see the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE.M_PT7_TU_PARALLAX', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE', 'Reads a scale from the side, so the reading is off.', '{"question":"How should your eye be placed when you read a measurement on a rule?","wrong_answer":"From the side, at an angle","correct_answer":"Straight above the mark"}'::jsonb, 'The learner looks from wherever they are standing and does not know the reading shifts.', 'Offer "From the side, at an angle" beside "Straight above the mark" and ask the child to choose.', 'Let two learners read the same mark from the left and right; they get different readings. Then both read from straight above.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE.M_PT7_TU_TRY_STOCK', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE', 'Lets the stock of the try-square float, or rests it on a rough edge, when marking a line square.', '{"question":"When marking a line square across a board, where is the stock of the try-square held?","wrong_answer":"Anywhere on the board","correct_answer":"Firmly against the straight face edge"}'::jsonb, 'The learner thinks the blade alone makes the right angle.', 'Offer "Anywhere on the board" beside "Firmly against the straight face edge" and ask the child to choose.', 'Mark two lines, one with the stock loose and one held against the face edge; check both with the square. Only the second is square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE.M_PT7_TU_PUNCH_FIRST', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_USE', 'Dot-punches the centre of a hole before scribing the lines that fix where it is.', '{"question":"When do you dot-punch the centre of a hole on a steel plate?","wrong_answer":"First, at a point that looks about right","correct_answer":"After scribing two lines that cross at the centre"}'::jsonb, 'The punch mark feels like the real start of the job.', 'Offer "First, at a point that looks about right" beside "After scribing two lines that cross at the centre" and ask the child to choose.', 'Scribe two crossing lines, then place the punch point where they meet. Show a plate punched first and how far off it is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE.M_PT7_TC_GAUGE_DIVIDER', 'PRET.G7.TOOLS_.MEASURING_AND_MARKING_OU.TOOL_CHOOSE', 'Picks dividers to mark a line parallel to the edge of a wooden plank, instead of a marking gauge.', '{"question":"Which tool marks a line parallel to the edge of a wooden plank?","wrong_answer":"Dividers","correct_answer":"A marking gauge"}'::jsonb, 'Both tools have a sharp point, so any pointed tool seems to mark lines.', 'Offer "Dividers" beside "A marking gauge" and ask the child to choose.', 'Show the marking gauge stock running along the edge while the spur marks; compare dividers, which swing arcs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY.M_HW_PRINTER_IN', 'PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY', 'Thinks a printer is an input device.', '{"question":"A printer is a type of what?","wrong_answer":"Input device","correct_answer":"Output device (hardcopy)"}'::jsonb, 'The printer is plugged into the computer, so the learner thinks it sends things in.', 'Offer "Input device" next to the right answer and ask the question again in a new context.', 'Follow the direction: data flows from the computer to the printer, so it is output.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY.M_HW_MONITOR_HARD', 'PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY', 'Thinks a monitor gives hardcopy.', '{"question":"Which output is softcopy?","wrong_answer":"Printer","correct_answer":"Monitor"}'::jsonb, 'The learner thinks output must be on paper.', 'Offer "Printer" next to the right answer and ask the question again in a new context.', 'Softcopy is shown on a screen or played; hardcopy is printed on paper you can hold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY.M_HW_SCANNER_OUT', 'PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY', 'Thinks a scanner is an output device.', '{"question":"A scanner sends a picture into the computer. What is it?","wrong_answer":"Output device","correct_answer":"Input device"}'::jsonb, 'A scanner looks like a printer.', 'Offer "Output device" next to the right answer and ask the question again in a new context.', 'Scan a page and see it appear on screen: data goes into the computer, so it is input.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY.M_HW_STORAGE_INPUT', 'PRET.G7.TOOLS_.COMPUTER_HARDWARE.HW_CLASSIFY', 'Thinks a flash disk is an input or output device.', '{"question":"A flash disk keeps files. What is it?","wrong_answer":"Input device","correct_answer":"Storage device"}'::jsonb, 'The flash disk is plugged in to move files, so it seems to put things in.', 'Offer "Input device" next to the right answer and ask the question again in a new context.', 'Say storage keeps data for later; a flash disk can hold files on and off the computer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING.M_EM_ALL_WORKERS', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'Thinks every worker is an entrepreneur.', '{"question":"Who is an entrepreneur?","wrong_answer":"Anyone who has a job","correct_answer":"A person who starts and runs a business"}'::jsonb, '"Worker" and "business person" are used loosely in daily talk.', 'Offer "Anyone who has a job" next to the right answer and ask the question again in a new context.', 'Compare a teacher employed by a school and a woman who starts a tailoring shop; only she takes the risk and runs the business.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING.M_EM_RICH_ONLY', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'Thinks only rich people can be entrepreneurs.', '{"question":"Who can start a small business?","wrong_answer":"Only rich people","correct_answer":"Anyone with an idea and a plan"}'::jsonb, 'The learner pictures big companies when they hear "business".', 'Offer "Only rich people" next to the right answer and ask the question again in a new context.', 'List small Kenyan businesses that started with little money (mandazi stall, boda boda, shoe repair).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING.M_EM_OWNER_ONLY', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'Thinks entrepreneurship helps only the owner.', '{"question":"How does a posho mill help its community?","wrong_answer":"Only the owner gains","correct_answer":"It makes jobs, grinds maize and pays taxes"}'::jsonb, 'The learner sees the owner''s profit and not the jobs and service.', 'Offer "Only the owner gains" next to the right answer and ask the question again in a new context.', 'Map who gains from a posho mill: farmers, workers, families, the county (taxes).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES.M_EQ_GAMBLE', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'Thinks taking risks means gambling or acting without thinking.', '{"question":"What is a calculated risk?","wrong_answer":"Spending everything and hoping","correct_answer":"A risk taken after counting the cost"}'::jsonb, '"Risk" is linked with luck and betting in the learner''s world.', 'Offer "Spending everything and hoping" next to the right answer and ask the question again in a new context.', 'Compare a calculated risk (count costs, test a small batch) with gambling (hope with no plan).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES.M_EQ_GIVE_UP', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'Thinks a good entrepreneur stops after the first failure.', '{"question":"A first batch of soap did not sell. What does a determined entrepreneur do?","wrong_answer":"Give up","correct_answer":"Find out why and try again"}'::jsonb, 'A first failure feels final to the learner.', 'Offer "Give up" next to the right answer and ask the question again in a new context.', 'Tell the story of a trader who changed her product after a slow start; list what she learnt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES.M_EQ_LUCK', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'Thinks success in business is luck only.', '{"question":"Why does a business succeed?","wrong_answer":"Only luck","correct_answer":"Hard work, honesty and good planning"}'::jsonb, 'The learner sees success but not the work behind it.', 'Offer "Only luck" next to the right answer and ask the question again in a new context.', 'Interview (or read about) a local business owner: hours, planning, savings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES.M_EQ_CHEAT', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_QUALITIES', 'Thinks cheating customers is clever business.', '{"question":"A shopkeeper adds water to milk. Which quality is missing?","wrong_answer":"Creativity","correct_answer":"Honesty"}'::jsonb, 'Profit is put above everything, so cheating looks clever.', 'Offer "Creativity" next to the right answer and ask the question again in a new context.', 'Ask what happens when customers find out: they stop buying. Honesty keeps customers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS.M_EI_CAPITAL_FIRST', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS', 'Thinks a business needs a lot of money before it has an idea.', '{"question":"What comes first when starting a business?","wrong_answer":"A lot of money","correct_answer":"A good idea that meets a need"}'::jsonb, 'Money is the need people talk about most.', 'Offer "A lot of money" next to the right answer and ask the question again in a new context.', 'Order the steps: notice a need, form an idea, plan, then find the money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS.M_EI_NEW_ONLY', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS', 'Thinks a business idea must be completely new.', '{"question":"Can a business idea come from improving another business?","wrong_answer":"No, it must be new","correct_answer":"Yes, you can improve what others do"}'::jsonb, '"Original" and "useful" are mixed up.', 'Offer "No, it must be new" next to the right answer and ask the question again in a new context.', 'Show businesses that improved an old idea (a faster delivery, a cleaner kiosk).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS.M_EI_COPY_EXACT', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS', 'Thinks copying a neighbour exactly is a good idea.', '{"question":"A kiosk next door sells airtime and does well. What is a good idea?","wrong_answer":"Copy it exactly beside it","correct_answer":"Look for a need not yet met"}'::jsonb, 'Another business''s success looks easy to copy.', 'Offer "Copy it exactly beside it" next to the right answer and ask the question again in a new context.', 'Count customers: two identical kiosks side by side share them; look for an unmet need instead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS.M_EI_WASTE', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_IDEAS', 'Thinks waste has no value for a business idea.', '{"question":"What can old tyres become in a business?","wrong_answer":"Nothing, they are rubbish","correct_answer":"Sandals, flower pots or farm buckets"}'::jsonb, 'Waste is seen only as dirt.', 'Offer "Nothing, they are rubbish" next to the right answer and ask the question again in a new context.', 'Show items made from waste (tyre sandals, bottle-top art, briquettes from sawdust).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING.M_PT7_EM_GOODS_ONLY', 'PRET.G7.ENTREP.INTRODUCTION_TO_ENTREPRE.ENT_MEANING', 'Thinks an entrepreneur must sell goods, so a person who sells a service is not one.', '{"question":"A young woman starts a phone repair service. Is she an entrepreneur?","wrong_answer":"No, she does not sell goods","correct_answer":"Yes, she starts and runs a business that offers a service"}'::jsonb, 'Shops with goods on shelves are the businesses the learner sees most.', 'Offer "No, she does not sell goods" beside "Yes, she starts and runs a business that offers a service" and ask the child to choose.', 'Sort businesses into goods (kiosk, butchery) and services (salon, repair, transport); all are run by entrepreneurs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_LOCATION.M_UL_TOWN_ALWAYS', 'PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'Thinks the town centre is always the best place for any business.', '{"question":"Where is a posho mill best placed?","wrong_answer":"In the town centre","correct_answer":"Near homes that grow maize, with power"}'::jsonb, 'Towns have many people, so the learner thinks they are always best.', 'Offer "In the town centre" next to the right answer and ask the question again in a new context.', 'For a posho mill, ask where the maize is and where the customers live; map it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_LOCATION.M_UL_CHEAP_ONLY', 'PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'Thinks cheap rent is the only factor.', '{"question":"A site has cheap rent but no customers pass. What happens?","wrong_answer":"The business does well","correct_answer":"The business may fail"}'::jsonb, 'Low cost feels like the most important thing to the learner.', 'Offer "The business does well" next to the right answer and ask the question again in a new context.', 'Compare two sites: cheap with no customers and dearer on a busy road; count likely sales.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_LOCATION.M_UL_ANYWHERE', 'PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'Thinks the place does not matter.', '{"question":"Does the place matter to a salon?","wrong_answer":"No, anywhere will do","correct_answer":"Yes, near customers and with power and water"}'::jsonb, 'The learner thinks only about the product, not the place.', 'Offer "No, anywhere will do" next to the right answer and ask the question again in a new context.', 'List what a salon needs nearby: customers, water, power, security, transport.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_SIZE.M_US_BIGGER_BETTER', 'PRET.G7.ENTREP.UNIT.UNIT_SIZE', 'Thinks a bigger business is always better.', '{"question":"Is a big workshop always better than a small one?","wrong_answer":"Yes, always","correct_answer":"No, it depends on capital, market and skills"}'::jsonb, 'Big businesses look successful on adverts and buildings.', 'Offer "Yes, always" next to the right answer and ask the question again in a new context.', 'Compare a small bakery selling all its bread with a big one throwing half away; size must fit the market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_SIZE.M_US_WISH_ONLY', 'PRET.G7.ENTREP.UNIT.UNIT_SIZE', 'Thinks size depends only on the owner''s wish.', '{"question":"What limits the size of a business?","wrong_answer":"Only what the owner wants","correct_answer":"Capital, market, raw materials, skills and the law"}'::jsonb, 'The learner thinks a dream is enough to decide size.', 'Offer "Only what the owner wants" next to the right answer and ask the question again in a new context.', 'List what limits size: capital, market, raw materials, skills and labour, land, the law.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_SIZE.M_US_NO_MARKET', 'PRET.G7.ENTREP.UNIT.UNIT_SIZE', 'Ignores the size of the market when sizing a business.', '{"question":"A village has 20 families. How big a bakery fits?","wrong_answer":"A very big one","correct_answer":"A small one"}'::jsonb, 'The learner does not count customers before choosing size.', 'Offer "A very big one" next to the right answer and ask the question again in a new context.', 'Work out loaves a day for 20 families; compare with what a big bakery makes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_LOCATION.M_PT7_UL_RAW_FAR', 'PRET.G7.ENTREP.UNIT.UNIT_LOCATION', 'Places a unit that uses heavy, bulky raw materials far from where they come from.', '{"question":"A sawmill uses heavy logs. Where is it best placed?","wrong_answer":"In the city centre, far from the forest","correct_answer":"Near the forest, where the logs come from"}'::jsonb, 'The learner thinks of customers only and forgets the cost of moving heavy materials.', 'Offer "In the city centre, far from the forest" beside "Near the forest, where the logs come from" and ask the child to choose.', 'Work out the transport cost of moving logs 100 km against moving planks; the bulky load should travel least.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.UNIT.UNIT_SIZE.M_PT7_US_BUILDING', 'PRET.G7.ENTREP.UNIT.UNIT_SIZE', 'Thinks the size of a production unit is shown only by the size of its building.', '{"question":"Which of these shows the size of a production unit?","wrong_answer":"Only how big its building is","correct_answer":"The number of workers, the capital, the output and the machines"}'::jsonb, 'Size is a word the learner uses for how big something looks.', 'Offer "Only how big its building is" beside "The number of workers, the capital, the output and the machines" and ask the child to choose.', 'Compare a small room with ten machines and many workers to a big empty store; list the measures of size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS.M_FI_RICH_ONLY', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS', 'Thinks financial goals are only for rich people.', '{"question":"Who needs financial goals?","wrong_answer":"Only rich people","correct_answer":"Everyone who handles money"}'::jsonb, '"Goals" sound like big plans for big money.', 'Offer "Only rich people" next to the right answer and ask the question again in a new context.', 'Set a class goal: save 300 shillings for a football in 6 weeks; anyone with money can set goals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS.M_FI_WISH', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS', 'Treats a goal as a wish.', '{"question":"What makes a goal different from a wish?","wrong_answer":"Nothing, they are the same","correct_answer":"A goal has a plan and a date"}'::jsonb, 'In daily talk "I want" and "my goal" are used alike.', 'Offer "Nothing, they are the same" next to the right answer and ask the question again in a new context.', 'Turn a wish ("I want a bicycle") into a goal (amount, plan, date).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS.M_FI_WANTS_FIRST', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS', 'Puts wants before needs when setting goals.', '{"question":"A learner has little money. What comes first?","wrong_answer":"A new game","correct_answer":"School shoes, a need"}'::jsonb, 'Wants feel urgent and exciting.', 'Offer "A new game" next to the right answer and ask the question again in a new context.', 'Sort ten items into needs and wants; plan needs first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS.M_FI_NO_TIME', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_GOALS', 'Ignores the time available for a goal.', '{"question":"Which factor says how soon a goal can be reached?","wrong_answer":"Colour of the notebook","correct_answer":"Time and income"}'::jsonb, 'Time is not seen as part of a money plan.', 'Offer "Colour of the notebook" next to the right answer and ask the question again in a new context.', 'Compare saving 1,200 in 6 weeks and in 12 weeks with 100 a week; time changes what is possible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART.M_SM_LETTERS', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART', 'Gets the SMART letters wrong.', '{"question":"What does the A in SMART stand for?","wrong_answer":"Ambitious","correct_answer":"Achievable"}'::jsonb, 'The learner guesses a word that sounds good with the letter.', 'Offer "Ambitious" next to the right answer and ask the question again in a new context.', 'Write SMART down the side: Specific, Measurable, Achievable, Realistic, Time-bound; give an example for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART.M_SM_VAGUE', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART', 'Thinks "save more money" is a good goal.', '{"question":"Which is a SMART goal?","wrong_answer":"Save more money","correct_answer":"Save 1,200 shillings in 12 weeks by saving 100 shillings a week"}'::jsonb, 'The learner does not see what is missing from a short goal.', 'Offer "Save more money" next to the right answer and ask the question again in a new context.', 'Test "save more money" against each SMART letter; it fails four of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART.M_SM_NUMBER_ENOUGH', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART', 'Thinks any goal with a number is SMART.', '{"question":"A learner with 100 shillings a week aims to save 1 million shillings in a month. Is it SMART?","wrong_answer":"Yes, it has a number","correct_answer":"No, it is not realistic"}'::jsonb, 'A number makes a goal feel measurable, so it seems complete.', 'Offer "Yes, it has a number" next to the right answer and ask the question again in a new context.', 'Check a goal of 1 million in a month against income: not achievable or realistic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS.M_FN_SELL_PROFIT', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'Takes the selling price as the profit.', '{"question":"A trader buys a bag for 400 shillings and sells it for 500. What is the profit?","wrong_answer":"500 shillings","correct_answer":"100 shillings"}'::jsonb, 'The money received at the sale feels like the gain.', 'Offer "500 shillings" next to the right answer and ask the question again in a new context.', 'Write profit = selling price - buying price; work three examples with real items.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS.M_FN_ADD_WEEKS', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'Adds or subtracts instead of dividing to find the weeks needed to save.', '{"question":"To save 1,200 shillings at 100 shillings a week, how many weeks are needed?","wrong_answer":"1,300 weeks","correct_answer":"12 weeks"}'::jsonb, 'The learner combines the two numbers in the question without thinking what is asked.', 'Offer "1,300 weeks" next to the right answer and ask the question again in a new context.', 'Ask "how many 100s make 1,200?" with counters; that is division.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS.M_FN_ONE_ITEM', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'Gives the profit on one item as the profit on the whole batch.', '{"question":"A trader earns 10 shillings profit on each of 20 loaves. What is the total profit?","wrong_answer":"10 shillings","correct_answer":"200 shillings"}'::jsonb, 'The number of items is forgotten once one profit is found.', 'Offer "10 shillings" next to the right answer and ask the question again in a new context.', 'Draw 20 loaves, each with 10 shillings profit; add them up, then multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS.M_FN_BUY_SELL', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_NUMBERS', 'Subtracts the selling price from the buying price.', '{"question":"Buying 60, selling 75. Profit?","wrong_answer":"Minus 15 shillings","correct_answer":"15 shillings"}'::jsonb, 'The learner subtracts in the order the numbers appear.', 'Offer "Minus 15 shillings" next to the right answer and ask the question again in a new context.', 'Always start from the money that came in (selling price), then take away the cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART.M_PT7_SM_NO_DATE', 'PRET.G7.ENTREP.FINANCIAL_GOALS.FIN_SMART', 'Thinks a goal with an amount and an item is SMART even without a time.', '{"question":"\"I will save 500 shillings for a calculator.\" What is missing for it to be SMART?","wrong_answer":"Nothing, it is already SMART","correct_answer":"A time limit, such as within 10 weeks"}'::jsonb, 'The amount and the item feel like the whole plan.', 'Offer "Nothing, it is already SMART" beside "A time limit, such as within 10 weeks" and ask the child to choose.', 'Tick each SMART letter for the goal; T has no tick. Add "within 10 weeks by saving 50 shillings a week".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
